<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_admin();require_once __DIR__ . '/../includes/db.php';
$stats=[
 ['Users',(int)query_value($conn,'SELECT COUNT(*) FROM `USER`'),'bi-people'],
 ['Active skills',(int)query_value($conn,"SELECT COUNT(*) FROM `SKILL` WHERE status='active'"),'bi-lightbulb'],
 ['Bookings',(int)query_value($conn,'SELECT COUNT(*) FROM `SESSION_BOOKING`'),'bi-calendar-check'],
 ['Reviews',(int)query_value($conn,'SELECT COUNT(*) FROM `REVIEW`'),'bi-star'],
];
$popular=$conn->query("SELECT s.skill_id,s.title,u.F_name,u.L_name,COUNT(sb.booking_id) AS total_bookings FROM `SKILL` s JOIN `USER` u ON u.user_id=s.user_id LEFT JOIN `SESSION_BOOKING` sb ON sb.skill_id=s.skill_id GROUP BY s.skill_id,s.title,u.F_name,u.L_name HAVING COUNT(sb.booking_id)>0 ORDER BY total_bookings DESC,s.title ASC LIMIT 5")->fetch_all(MYSQLI_ASSOC);
$owners=$conn->query("SELECT u.user_id,u.F_name,u.L_name,COUNT(sb.booking_id) AS sessions_received FROM `USER` u JOIN `SKILL` s ON s.user_id=u.user_id JOIN `SESSION_BOOKING` sb ON sb.skill_id=s.skill_id GROUP BY u.user_id,u.F_name,u.L_name ORDER BY sessions_received DESC LIMIT 5")->fetch_all(MYSQLI_ASSOC);
$ratings=$conn->query("SELECT u.user_id,u.F_name,u.L_name,ROUND(AVG(r.rating),2) AS avg_rating,COUNT(r.booking_id) AS review_count FROM `USER` u JOIN `SKILL` s ON s.user_id=u.user_id JOIN `SESSION_BOOKING` sb ON sb.skill_id=s.skill_id JOIN `REVIEW` r ON r.booking_id=sb.booking_id GROUP BY u.user_id,u.F_name,u.L_name HAVING COUNT(r.booking_id)>0 ORDER BY avg_rating DESC,review_count DESC LIMIT 5")->fetch_all(MYSQLI_ASSOC);
$statuses=$conn->query("SELECT session_status,COUNT(*) AS total FROM `SESSION_BOOKING` GROUP BY session_status ORDER BY total DESC")->fetch_all(MYSQLI_ASSOC);
$categories=$conn->query("SELECT COALESCE(NULLIF(category_name,''),'Uncategorized') AS category_name,COUNT(*) AS total FROM `SKILL` GROUP BY COALESCE(NULLIF(category_name,''),'Uncategorized') ORDER BY total DESC LIMIT 8")->fetch_all(MYSQLI_ASSOC);
$newUsers=$conn->query("SELECT user_id,F_name,L_name,join_date,status FROM `USER` WHERE join_date >= DATE_SUB(CURDATE(),INTERVAL 30 DAY) ORDER BY join_date DESC,user_id DESC LIMIT 8")->fetch_all(MYSQLI_ASSOC);
$pageTitle='Admin dashboard';require __DIR__.'/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="eyebrow text-primary mb-1">System overview</div><h1 class="section-title h2 mb-0">Admin dashboard</h1></div><span class="badge badge-soft rounded-pill px-3 py-2">Live SQL reports</span></div>
<div class="row g-3 mb-4"><?php foreach($stats as[$label,$value,$icon]):?><div class="col-6 col-lg-3"><div class="card stat-card h-100"><div class="card-body d-flex gap-3 align-items-center"><span class="stat-icon"><i class="bi <?=e($icon)?>"></i></span><div><div class="h3 fw-bold mb-0"><?=(int)$value?></div><div class="text-secondary small"><?=e($label)?></div></div></div></div></div><?php endforeach;?></div>
<div class="row g-4 mb-4"><div class="col-lg-4"><div class="surface-card p-4 h-100 admin-accent"><h2 class="h5">Most popular skills</h2><?php if(!$popular):?><p class="text-secondary small">No booking data yet.</p><?php endif;?><?php foreach($popular as $i=>$row):?><div class="d-flex justify-content-between py-2 border-bottom"><div><span class="text-secondary me-2"><?=($i+1)?>.</span><strong><?=e($row['title'])?></strong><div class="small text-secondary ms-4"><?=e(trim($row['F_name'].' '.$row['L_name']))?></div></div><span class="badge badge-soft align-self-start"><?=(int)$row['total_bookings']?></span></div><?php endforeach;?></div></div>
<div class="col-lg-4"><div class="surface-card p-4 h-100"><h2 class="h5">Most active mentors</h2><?php if(!$owners):?><p class="text-secondary small">No mentor activity yet.</p><?php endif;?><?php foreach($owners as $row):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=e(trim($row['F_name'].' '.$row['L_name']))?></span><strong><?=(int)$row['sessions_received']?></strong></div><?php endforeach;?></div></div>
<div class="col-lg-4"><div class="surface-card p-4 h-100"><h2 class="h5">Highest-rated mentors</h2><?php if(!$ratings):?><p class="text-secondary small">No ratings yet.</p><?php endif;?><?php foreach($ratings as $row):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=e(trim($row['F_name'].' '.$row['L_name']))?></span><span class="rating-stars"><i class="bi bi-star-fill"></i> <?=e($row['avg_rating'])?> <small class="text-secondary">(<?=(int)$row['review_count']?>)</small></span></div><?php endforeach;?></div></div></div>
<div class="row g-4"><div class="col-lg-4"><div class="surface-card p-4 h-100"><h2 class="h5">Bookings by status</h2><?php foreach($statuses as $row):?><div class="d-flex justify-content-between py-2"><span><span class="badge text-bg-<?=e(status_class($row['session_status']))?> me-2"><?=e(ucfirst($row['session_status']))?></span></span><strong><?=(int)$row['total']?></strong></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="surface-card p-4 h-100"><h2 class="h5">Skills by category</h2><?php foreach($categories as $row):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=e($row['category_name'])?></span><strong><?=(int)$row['total']?></strong></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="surface-card p-4 h-100"><h2 class="h5">New users - 30 days</h2><?php if(!$newUsers):?><p class="text-secondary small">No recent registrations.</p><?php endif;?><?php foreach($newUsers as $row):?><div class="d-flex justify-content-between py-2 border-bottom"><div><?=e(trim($row['F_name'].' '.$row['L_name']))?><div class="small text-secondary"><?=e(date('M j',strtotime($row['join_date'])))?></div></div><span class="badge text-bg-<?=e(status_class($row['status']))?> align-self-center"><?=e($row['status'])?></span></div><?php endforeach;?></div></div></div>
</div></section>
<?php require __DIR__.'/../includes/footer.php';?>
